-- Forever creatures: quest drops that did not show on the creature's tooltip (same cause as the Zephras Isle file before this).
-- The tooltip's quest line comes from the creature's quest item list (creature_questitem, sent with the creature query).
-- Our Forever rows there came only from the sniff's creature queries, so drops added to our loot later had no row:
-- the item dropped, but hovering the creature showed only its name and level.
-- Rows: every spawned Forever creature (entry 200000+) whose loot has a quest item (item class Quest or Miscellaneous)
-- that a quest objective asks for, with no row for it yet. Common goods (cloth, leather, gems, potions, food) are left out,
-- as their quests do not mark every creature that can drop them.
-- Idx follows the rows these creatures already have. Clients that cached the creature need the Cache folder cleared once.
DELETE FROM `creature_questitem` WHERE `DifficultyID`=0 AND (`CreatureEntry`,`ItemId`) IN
((209797,253710),(214519,209778),(214519,271872),(228610,18335),(246664,275997),(246752,7293),(248278,780),(248278,247826),(248299,3253),(248299,247862),(248464,772),(248464,773),(248464,248002),(248474,772),(248474,773),(248474,248003),(250621,268540),(250621,268580),(250660,280438),(253272,6067),(255066,2794),(255560,6067),(259897,6845),(260157,267414),(260325,271100),(260325,284845),(260326,270865),(260326,270866),(260396,268812),(260800,271100),(260800,284845),(260801,271100),(260801,284845),(260802,284845),(260808,270180),(261485,5078),(262119,270151),(262838,6067),(264081,273181),(264096,273001),(266216,3692),(266849,3412),(266851,275722),(266852,275723),(267109,5383),(267307,276070),(268530,277128),(268558,270302),(268605,277269),(268624,5085),(268624,277277),(269134,2794),(270196,281038),(270294,279275),(270693,279591),(270892,279993),(271334,11407),(271338,280395),(271338,280398),(271346,3337),(271348,3337),(271351,3337),(271460,280396),(271460,280398),(271462,280397),(271462,280398),(271486,2671),(271587,280426),(271903,280686),(272034,280831),(272044,280832),(272046,280834),(272096,3412),(272116,281023),(272173,281048),(272260,281143),(272273,281142),(272284,281145),(272291,281147),(275662,286008),(275663,286008),(275708,286017),(276009,286325),(276061,1274),(276099,286017),(276180,780),(276198,4892));
